import numpy as np
z=np.load('/app/output/overhead0.npz'); im=z['rgb']; dep=z['depth']; K=z['K']; E=z['cam'];
for name,mask in [('blue',(im[:,:,2]>200)&(im[:,:,0]<50)&(im[:,:,1]<100)),('red',(im[:,:,0]>200)&(im[:,:,1]<100)&(im[:,:,2]<100))]:
 y,x=np.where(mask); d=np.median(dep[y,x]); u=np.median(x);v=np.median(y); f=K[0,0];
 pts=np.c_[(x-K[0,2])*dep[y,x]/f, -(y-K[1,2])*dep[y,x]/f, -dep[y,x], np.ones(len(x))] @ E.T
 print(name,'medianpix',u,v,'depth',d,'world med',np.median(pts[:,:3],axis=0),'world percentile',np.percentile(pts[:,:3],[10,50,90],axis=0))
